match
$m isa movie, has revenue $rev;
$p isa person, has person_name $name;
$rel isa crew_for (crew_member: $p, film: $m), has job "Director";
reduce $total_revenue = sum($rev) groupby $p;
sort $total_revenue desc;
limit 3;
